+        }
+    }
+
+    @Override
+    public void close() {
+        Releasables.close(values, super::close);
+    }
+
+    /**
+     * Returns the index of the ip at {@code groupId}
+     */
+    private int getIndex(int groupId) {
+        return groupId * IP_LENGTH;
+    }
